            try:
                self.quiesce(type(exc).__name__ + ': ' + str(exc))
            except BaseException as cleanup:
                self.park('PRIMARY_ERROR: ' + repr(exc) + '; CLEANUP_UNKNOWN: ' + repr(cleanup))
